// TestCmdLiveStart 获取直播开始信息
//
//	go test -v -run TestCmdLiveStart ./test/
func TestCmdLiveStart(t *testing.T) {
	for i, raw := range LIVE {
		info, err := live.ExtractLive(raw)
		if err != nil {
			t.Errorf("第 %d 条消息解析失败: %v", i, err)
			continue
		}
		t.Logf("第 %d 条:", i+1)
		t.Logf("  直播ID: %s", info.LiveKey)
		t.Logf("  直播平台: %s", info.LivePlatform)
		t.Logf("  开播时间: %d", info.LiveTime)
		t.Logf("  ---")
	}
}

